import type { Ingredient, RecipeSource } from "../types";
import { KNIFE, SPOONS, STOVE, pot, type AmountSource, type Seed, type SeedIngredient } from "./shared";

// DISHES REWRITTEN FROM THE YOUTUBE CHANNELS MOTHER WATCHES.
//
// Rules for this file (CLAUDE.md, rule 5):
// - Amounts are only those the channel itself publishes in the video description. Where the
//   channel gives no amount the ingredient is "một ít" (quantity null, unit "it") — never a
//   number made up here. Grams next to a spoon amount appear only where the channel gives them.
//   An amount the channel only says aloud is used too, and named in source.note with its time
//   when it was read from an automatic transcript.
// - The order of work, heat and times are what the channel says in the video (read from
//   YouTube's transcript; the picture was not watched). Nothing the channel does not say is
//   written as if it did. The wording is this app's own, not copied.
// - "Được khi…" and "Tránh…" come from what the channel says at that point of the video. Where
//   the channel says nothing, the line is an ordinary kitchen observation, marked `// own` here
//   and counted in source.note.
// - Every step carries the seconds of the video where it is shown (clip), so the cook — and
//   whoever reviews this file — can watch exactly that part.
// - Channels usually list every ingredient and amount first and only then start working, while
//   the steps here follow the work. So a dish also carries the part of the video where the
//   ingredients are listed (ingredientsClip, shown before step 1), and every amount says where it
//   comes from: DESC (the video's description) or said("0:54", "0:56"), the seconds in which the
//   channel says it, read from the word timings of the video's captions. tests/video-seeds.test.ts
//   checks that every spoken amount can be heard in the ingredients part or in the part of a step
//   that uses it, and that no part starts or ends in the middle of an amount being said.
// - Anything the writer had to estimate (servings, total minutes) is named in source.note,
//   which the recipe page shows.
// - Stored as verification = "entered": "Mới nhập – chưa nấu thử" until the family approves it.

const video = (id: string, title: string, creatorName: string, note: string, ingredients?: { ingredientsVideoStartSeconds: number; ingredientsVideoEndSeconds: number }): RecipeSource => ({
  kind: "youtube",
  title,
  creatorName,
  url: `https://www.youtube.com/watch?v=${id}`,
  youtubeVideoId: id,
  fidelity: "transcribed",
  note,
  ...ingredients,
});

type Extra = Partial<Pick<Ingredient, "optional" | "prepNote" | "tasteRole" | "scales" | "metricQuantity" | "metricUnit">> & { amountSource?: AmountSource };
type Amount = [number, NonNullable<Ingredient["unit"]>] | "it";
const item = (kind: Ingredient["kind"], group: string) => (slot: string, name: string, amount: Amount, extra: Extra = {}): SeedIngredient => ({
  slot,
  name,
  kind,
  group,
  quantity: amount === "it" ? null : amount[0],
  unit: amount === "it" ? "it" : amount[1],
  metricQuantity: null,
  metricUnit: null,
  ...extra,
});
const food = item("food", "Nguyên liệu");
const season = item("seasoning", "Gia vị");
// A dish in two parts, as the channel lists it.
const meatball = item("food", "Thịt viên");
const meatballSeason = item("seasoning", "Gia vị trộn thịt");
const sauce = item("seasoning", "Sốt chua ngọt");
const ramSauce = item("seasoning", "Sốt ram");
const stirSauce = item("seasoning", "Sốt xào");
const scallionOil = item("seasoning", "Mỡ hành");
// A cake in three parts.
const crust = item("food", "Vỏ bánh");
const fillingFood = item("food", "Nhân bánh");
const glaze = item("food", "Hoàn thiện");
const filling = item("seasoning", "Gia vị ướp nhân");
const braise = item("seasoning", "Nước kho");
/** The gram weight the channel itself gives next to a spoon amount. */
const grams = (g: number) => ({ metricQuantity: g, metricUnit: "g" as const });
const all = (...slots: string[]) => slots.map((slot) => ({ slot, portion: 1 }));
/** "1:22" → 82. */
const at = (time: string) => time.split(":").reduce((n, part) => n * 60 + Number(part), 0);
const clip = (from: string, to: string) => ({ videoStartSeconds: at(from), videoEndSeconds: at(to) });
/** The part of the video where the channel lists the ingredients. */
const ingredientsClip = (from: string, to: string) => ({ ingredientsVideoStartSeconds: at(from), ingredientsVideoEndSeconds: at(to) });
/** The amount is said in the video, between these two times. */
const said = (from: string, to: string) => ({ amountSource: { saidFrom: at(from), saidTo: at(to) } });
/** The amount is written in the video's description. */
const DESC = { amountSource: "description" as const };

